<?php

namespace Modules\Finance\Models;
use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasMany;use Modules\Core\Models\Concerns\BelongsToCompany;use Modules\MasterData\Models\Customer;
class ArInvoice extends Model{use BelongsToCompany;public const STATUSES=['OPEN','PARTIAL','PAID','VOID'];protected $fillable=['company_id','doc_no','customer_id','sales_order_id','shipment_id','invoice_date','due_date','currency_id','exchange_rate','subtotal_amount','tax_amount','withholding_amount','total_amount','base_amount','finance_finalized_at','paid_amount','status','created_by','updated_by'];protected function casts():array{return['invoice_date'=>'date','due_date'=>'date','exchange_rate'=>'decimal:12','subtotal_amount'=>'decimal:4','tax_amount'=>'decimal:4','withholding_amount'=>'decimal:4','total_amount'=>'decimal:4','base_amount'=>'decimal:4','finance_finalized_at'=>'datetime','paid_amount'=>'decimal:4'];}public function lines():HasMany{return$this->hasMany(ArInvoiceLine::class);}public function payments():HasMany{return$this->hasMany(ArPayment::class);}public function customer():BelongsTo{return$this->belongsTo(Customer::class);}public function taxLines():HasMany{return$this->hasMany(FinanceTaxLine::class,'document_id')->where('document_type','AR_INVOICE');}public function outstanding():float{return(float)$this->total_amount-(float)$this->paid_amount;}}
